// CSD_RATIONALE_BEGIN
// Root cause analysis (after attempts 72-74):
// - Best result 53.3% (attempt 72) uses CloseSpanWithinBudget(400) with
//   format-focused guidance. Attempts 73 and 74 both regressed when adding
//   semantic rules (4-rule guidance: -5.3pp; ranking hint: -1.3pp). Pattern:
//   more guidance = worse for this 4B model.
//
// Failure mode (mode_A, 144/300 wrong): semantic errors — wrong column selection,
//   extra columns, wrong aggregation. Examples from rollouts:
//   Q: "age and hometown of every teacher" → "SELECT name, age FROM teacher"
//   Q: "all student details reversed" → SELECT all columns instead of "other_student_details"
//
// Key hypothesis: Attempt 72's guidance ("Output SQL: <<query>> where ... The SQL
//   must be placed between << and >>...") spends token budget on format reminders
//   that the evaluator/prompt already provides, leaving no room for semantic
//   instruction. Attempts 73-74 ADDED to this, making it worse.
//
// Change: Replace attempt 72's guidance with a shorter, column-accuracy-focused
//   string that drops redundant format text and targets the #1 failure: wrong/extra
//   column selection. Structure remains identical to attempt 72 (best baseline):
//   Phase1: 5-step preamble → Phase2: force << → Phase3: CloseSpanWithinBudget(400).
//
// Budget: 5 (preamble) + 1 (force <<) + 400 (SQL) = 406 << 900. All within spec.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the implication
//   is vacuously true throughout. The only true-flip comes from RenderedEndsWith("<<");
//   we immediately set currentConstrainedOut := [] and IsValidPrefix([]) holds by
//   the method precondition. EOS break leaves insideConstrainedOut unchanged (false).
//
// Phase 2 OpenConstrainedSpan: Executes only when !insideConstrainedOut. Its
//   postcondition sets currentConstrainedOut := [] and insideConstrainedOut := true;
//   IsValidPrefix([]) holds by the method precondition.
//
// Phase 3 CloseSpanWithinBudget: Postcondition directly guarantees both
//   (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)),
//   covering closed and open-span exit paths.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step, appends at most 1 token (0 on EOS).
//   Each iteration: steps += 1, |generated| grows by <= 1. Invariant preserved.
//
// Phase 2: OpenConstrainedSpan costs 1 step, appends exactly 1 "<<" token.
//   steps += 1, |generated| += 1. Preserved 1:1.
//
// Phase 3: closeBudget <= maxSteps - steps_before. CloseSpanWithinBudget
//   postcondition: |cg| <= |generated| + closeBudget. We set steps += closeBudget,
//   so |cg| <= |generatedPrefix| + new_steps. Tokens consumed for dead-end
//   avoidance or EOS that are not visibly appended still count against closeBudget,
//   so visible growth is bounded by closeBudget as required. cost = steps <= maxSteps.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>>. SELECT only the exact column(s) that the question asks for by name. Do not add extra columns. Use exact table and column names from the schema. No explanation.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate full SQL and close span using CloseSpanWithinBudget.
// Budget=400 gives the LM room to generate WHERE/JOIN/GROUP BY/ORDER BY.
// CloseSpanWithinBudget tracks the LONGEST complete prefix seen during
// generation (not the first), preventing premature-termination failures.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 400 {
    closeBudget := remaining;
  } else {
    closeBudget := 400;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

